/**
 * Physical game cases — one parametric model per platform, used by `game-[slug].mjs`
 * (a helper file: names starting with "_" never match a catalogue key).
 *
 *   nintendo     red case            105 × 170 × 11 mm
 *   playstation  clear case, blue-topped cover   135 × 171 × 14 mm
 *   xbox         green case          135 × 171 × 14 mm
 *
 * A case stands upright, cover towards +Z, spine at −X (it opens on the right). It is a lid and a
 * tray with a hairline seam between them, a thumb notch on the opening edge, and the printed
 * sheet lying on the lid. The sheet is generated by `_game-cover.mjs`: the title in type on an
 * abstract pattern in the platform colour under a plain band. No cover art, no logos.
 */
import { paintCover, PX_PER_MM } from './_game-cover.mjs';
import { paintSteady, printed, tones } from './_print.mjs';

export const GAME_CASES = {
  nintendo: { size: [105, 170, 11], corner: 3, edge: 1.5, band: 0.082, shell: 'clay' },
  playstation: { size: [135, 171, 14], corner: 3.6, edge: 1.8, band: 0.103, shell: 'clear' },
  xbox: { size: [135, 171, 14], corner: 3.6, edge: 1.8, band: 0.09, shell: 'clay' },
};

/**
 * @param kit      the scene kit
 * @param options  { platform, title, slug, color } — `color` is the platform colour (#rrggbb)
 */
export function buildGameCase(kit, { platform, title, slug, color }) {
  const spec = GAME_CASES[platform];
  if (!spec) throw new Error(`game case: no model for platform "${platform}" (have ${Object.keys(GAME_CASES).join(', ')})`);
  const { clay, clear, hollow } = kit;
  const PROUD = 0.45; // how far the printed sheet stands off the plastic
  // The catalogue size is the finished case: the plastic shell is that less the sheet on the
  // front, on the back and on the spine.
  const W = spec.size[0] - PROUD, H = spec.size[1], D = spec.size[2] - 2 * PROUD;
  const FRONT = D / 2;
  const SEAM = 0.6, LID = D * 0.4, TRAY = D - LID - SEAM; // lid in front, tray behind
  const SEAM_Z = FRONT - LID - SEAM / 2;
  const isClear = spec.shell === 'clear';
  const print = tones(color);
  const parts = [];
  const add = (geometry, material, at, extra) => parts.push(kit.mesh(geometry, material, { at, ...extra }));

  // ── shell: lid and tray ──────────────────────────────────────────────────
  const outline = kit.rect(W, H, spec.corner);
  const plastic = isClear ? clear('#d3e2f6', { opacity: 0.42 }) : clay(color, { finish: 'satin' });
  const shell = { cast: !isClear }; // a clear shell must not throw a solid shadow
  add(kit.slab(outline, LID, { bevel: spec.edge, bevelBack: 0.3 }), plastic, [0, 0, FRONT - LID / 2], shell);
  add(kit.slab(outline, TRAY, { bevel: 0.3, bevelBack: spec.edge }), plastic, [0, 0, -FRONT + TRAY / 2], shell);
  if (isClear) {
    // what a clear case shows through its walls: the paper and the tray inside, and the seam as a faint line
    const wall = 1.7;
    add(kit.slab(kit.rect(W - 2 * wall, H - 2 * wall, spec.corner - 1), D - 2, { bevel: 0.9 }), clay('#e9eef6'), [0, 0, 0]);
    add(kit.slab(kit.rect(W - 1.1, H - 1.1, spec.corner - 0.5), SEAM, { bevel: 0 }), clay('#7f93ae', { finish: 'soft' }), [0, 0, SEAM_Z]);
  } else {
    add(kit.slab(kit.rect(W - 1.3, H - 1.3, spec.corner - 0.6), SEAM + 1.2, { bevel: 0 }), hollow(), [0, 0, SEAM_Z]); // the dark of the seam
  }

  // ── thumb notch on the opening edge ──────────────────────────────────────
  parts.push(kit.vents([[0, 0]], { size: [SEAM + 2.6, 24], at: [W / 2, 0, SEAM_Z], rot: [0, 90, 0], material: hollow(isClear ? '#55657c' : '#060607') }));

  // ── printed sheet: front, spine, back ────────────────────────────────────
  const rim = spec.edge + 1.3, rimSpine = spec.edge + 0.3; // the shell shows as a frame around the sheet
  const sheetW = W - rim - rimSpine, sheetH = H - 2 * rim, sheetX = (rimSpine - rim) / 2;
  const cover = paintSteady(kit, Math.round(sheetW * PX_PER_MM), Math.round(sheetH * PX_PER_MM), (ctx, w, h) => {
    paintCover(ctx, w, h, { title, slug, color, band: spec.band });
  });
  const SHEET = 0.5, lift = PROUD - SHEET / 2; // sheet thickness, and where its middle sits above the plastic
  add(kit.slab(kit.rect(sheetW, sheetH, 0.9), SHEET, { bevel: 0.14 }), printed(kit, cover), [sheetX, 0, FRONT + lift]);
  add(kit.slab(kit.rect(sheetW, sheetH, 0.9), SHEET, { bevel: 0.14, axis: '-z' }), clay(print.ink, { finish: 'satin' }), [sheetX, 0, -FRONT - lift]);
  const spineW = D - 2 * spec.edge - 0.3, bandH = sheetH * spec.band;
  add(kit.slab(kit.rect(spineW, sheetH - bandH, 0.4), SHEET, { bevel: 0.14, axis: '-x' }), clay(print.ink, { finish: 'satin' }), [-W / 2 - lift, -bandH / 2, 0]);
  add(kit.slab(kit.rect(spineW, bandH, 0.4), SHEET, { bevel: 0.14, axis: '-x' }), clay(color, { finish: 'satin' }), [-W / 2 - lift, (sheetH - bandH) / 2, 0]);

  return kit.group(parts);
}
